float sht4x_convertRawTemperature(uint16_t temperatureRaw) {
	float temperature = 0.0;
	temperature = (float)(temperatureRaw);
	temperature = ((temperature * 175.0) / 65535.0) - 45.0;
	return temperature;
}

float sht4x_convertRawHumidity(uint16_t humidityRaw) {
	float humidity = 0.0;
	humidity = (float)(humidityRaw);
	humidity = ((humidity * 125.0) / 65535.0) - 6.0;
	return humidity;
}

static void sht4x_getVal1andVal2(const uint8_t *buffer, uint16_t *val1, uint16_t *val2) {
	*val1 = ((uint16_t)buffer[0]<<8) | (uint16_t)buffer[1];
	*val2 =	((uint16_t)buffer[3]<<8) | (uint16_t)buffer[4];
}

