int32_t sht4x_serialNumber(const stmdev_ctx_t *ctx, uint32_t* serialNumber) {
	int32_t localError = NO_ERROR;
	uint8_t write_buffer[1], read_buffer[6];
	uint16_t val1, val2;

	write_buffer[0] = SHT4X_SERIAL_NUMBER_CMD_ID;
	localError = ctx->write_i2c(ctx->handle, write_buffer, 1); // Envoi de la commande

	if (!localError) {
		ctx->mdelay(10);

		// pas de contrôle du status, se termine par NACK
		localError = ctx->read_i2c(ctx->handle, read_buffer, 6); // Récupération du serial number

		if (!localError) {
			sht4x_getVal1andVal2(read_buffer, &val1, &val2);
			*serialNumber = ((uint32_t)val1<<16) | (uint32_t)val2;
		}
	}

	return localError;
}

int32_t sht4x_softReset(const stmdev_ctx_t *ctx) {
	int32_t localError = NO_ERROR;
	uint8_t write_buffer[1];

	write_buffer[0] = SHT4X_SOFT_RESET_CMD_ID;

	localError = ctx->write_i2c(ctx->handle, write_buffer, 1); // Envoi de la commande
	if (!localError) ctx->mdelay(10);

	return localError;
}

